def _inside(rings, lon, lat):
    inside = False
    for ring in rings:
        j = len(ring) - 2
        for i in range(0, len(ring), 2):
            xi, yi, xj, yj = ring[i], ring[i + 1], ring[j], ring[j + 1]
            if (yi > lat) != (yj > lat) and lon < (xj - xi) * (lat - yi) / (yj - yi) + xi:
                inside = not inside
            j = i
    return inside


def operation_for(base_epsg, lon, lat):
    """(EPSG op code, region name or None) for a point of a datum; None if not ours."""
    entry = DATUM_OPS.get(base_epsg)
    if entry is None:
        return None
    for name, code, rings in entry["regions"]:
        if _inside(rings, lon, lat):
            return code, name
    return entry["default"], None


def default_operation(base_epsg):
    entry = DATUM_OPS.get(base_epsg)
    return None if entry is None else entry["default"]
